/* CRM_UNIT:backfillClosedHistoricalShifts-25b9ad1fd867 */async function backfillClosedHistoricalShifts(){
 const button=$('#backfillClosedShifts');
 const show=(text,kind='')=>{const status=$('#backfillStatus');if(status){status.hidden=false;status.className='notice'+(kind?' '+kind:'');status.textContent=text}};
 if(currentUser().role!=='owner'){show('Операцию может выполнить только владелец.','warn');return}
 if(!window.MasterAICloud?.connected){show('Нет соединения с общей базой. Исторические смены не записаны.','warn');return}
 if(button){button.disabled=true;button.textContent='Проверяю ведомость…'}
 let savedCount=0,skipped=0;
 try{
  const history=state.payrollHistory,rows=history?.days;
  if(!Array.isArray(rows)||!rows.length)throw new Error('Историческая ведомость не загружена');
  const todayIso=today(),staff=(state.settings.staff||[]).filter(p=>p.active!==false&&['dispatcher_logistic','logistic'].includes(p.role)&&p.id);
  const eligible=rows.filter(r=>r&&/^\d{4}-\d{2}-\d{2}$/.test(String(r.date||''))&&r.date<todayIso).sort((a,b)=>a.date.localeCompare(b.date)||String(a.person).localeCompare(String(b.person)));
  if(!eligible.length)throw new Error('В ведомости нет закрытых дат до сегодняшнего дня');
  if(eligible.length>120)throw new Error('Ведомость превышает безопасный лимит 120 смен');
  const seen=new Set(),plan=[];
  for(const row of eligible){
   const shift=String(row.person||''),key=row.date+'-'+shift;
   if(seen.has(key))throw new Error('В ведомости повторяется смена '+key);
   seen.add(key);
   const name=shift==='sergey'?'сергей':'артем',digit=shift==='sergey'?'1':'2';
   const member=staff.find(p=>p.shift===shift||p.shift===digit||norm(p.name)===name);
   if(!member)throw new Error('Не найден активный профиль '+(shift==='sergey'?'Сергея':'Артёма')+' для смены '+row.date);
   const existing=state.shiftReports.find(r=>r.date===row.date&&payrollShiftKey(r)===shift);
   if(existing&&(shiftIntegrity(existing)||(existing.ownerConfirmed&&existing.subjectMemberId))){skipped++;continue}
   const draft=historicalPayrollShiftSnapshot(row,{...member,shift});
   draft.closedBy=currentUser().id;draft.closedByName=currentUser().name;
   draft.subjectMemberId=member.id;draft.approvedFor=member.id;draft.approvedForName=member.name;
   draft.ownerConfirmed=true;draft.ownerApprovedBy=currentUser().id;draft.ownerApprovedByName=currentUser().name;
   // Keep the immutable legacy document untouched. The canonical owner report
   // uses only fields permitted by the Firestore shift-report schema.
   plan.push(draft)
  }
  if(!plan.length){show('Все '+skipped+' исторических смен уже закрыты по ведомости.','ok');return}
  show('Подготовлено '+plan.length+' отчётов. Будет записана только одна смена за нажатие; подтверждение — от владельца.');
  if(button)button.textContent='Записываю одну смену…';
  const draft=plan[0];
   const result=await window.MasterAICloud.confirmShiftDraft(draft);
   const persisted=await window.MasterAICloud.getShiftReportsForPeriod(draft.date,draft.date);
   const verified=persisted.find(r=>r.id===draft.id&&shiftIntegrity(r));
   if(!verified)throw new Error('Firestore не подтвердил сохранение отчёта '+draft.date);
   state.shiftReports=[verified,...state.shiftReports.filter(r=>r.id!==verified.id)];
  savedCount=1;
  await dbWrite();renderShiftClose();renderWeeklyReports();
   const remaining=Math.max(0,plan.length-1);
  show('Отчёт владельца записан за '+draft.date+' · '+draft.approvedForName+'. Осталось смен: '+remaining+'. Новые выплаты не создавались.','ok');
  toast('Записан один исторический отчёт владельца')
  }catch(error){
   let renderError='';
   try{renderShiftClose();renderWeeklyReports()}catch(e){renderError=' Не удалось обновить экран: '+(e.message||e)}
   show('Заполнение остановлено после '+savedCount+' записей. '+(error.message||error)+renderError,'warn');
  toast('Не удалось заполнить отчёты: '+(error.message||error))
 }finally{
  const current=$('#backfillClosedShifts');
  if(current){current.disabled=false;current.textContent='Записать одну смену'}
 }
}/* CRM_END:backfillClosedHistoricalShifts-25b9ad1fd867 */
