async function closeCurrentShift(){if(currentUser().role!=='owner'){toast('Отчёт автоматически подготовится владельцу после смены');return}if(!window.MasterAICloud?.connected){toast('Нет связи с общей базой. Смена не закрыта; подключитесь и повторите.');return}const report=shiftSnapshot();if(state.shiftReports.some(r=>r.id===report.id)){toast('Эта смена уже закрыта');return}try{let saved=report;if(window.MasterAICloud?.connected)saved=await window.MasterAICloud.closeShift(report);state.shiftReports=[{...report,...saved,closureOnly:true},...state.shiftReports];log('shift',`Закрыта ${report.shiftName}: ${report.orders} заказов`);await dbWrite();renderShiftClose();toast('День закрыт. Заказы в отчёте заблокированы для изменений')}catch(e){toast('Не удалось закрыть смену: '+(e.message||e))}}/* CRM_END:closeCurrentShift-732d417b56f5 */
/* CRM_UNIT:payrollDailyEstimate-50f83c29ef78 */
function payrollDailyEstimate(entries,cutoff=today()){const days=new Map();for(const x of entries){if(x.used||!x.assignedDate||x.assignedDate>cutoff)continue;days.set(x.assignedDate,(days.get(x.assignedDate)||0)+Math.round(x.cash*100))}return{days:days.size,salary:Math.round([...days.values()].reduce((total,cents)=>total+Math.round(shiftPayroll(cents/100)*100),0))/100}}/* CRM_END:payrollDailyEstimate-50f83c29ef78 */
